export default function TruchetPattern({
  width = "100%",
  height = "100%",
  color = "#ffffff",
  backgroundColor = "#000000",
  opacity=0.5,
}) {
  const xml = useMemo(
    () => originalSvg.replaceAll('fill="#ffffff"', `fill="${color}"`),
    [color]
  );

  return (
    <View style={{ width, height, backgroundColor, overflow: "visible", position: "absolute", opacity}}>
      <SvgXml xml={xml} width="100%" height="100%" preserveAspectRatio="xMidYMid slice" />
    </View>
  );
}
